void freeLuaRedisArgv(robj **argv, int argc, int argv_len);


static robj **luaArgsToRedisArgv(lua_State *lua, int *argc, int *argv_len) {
    luaRuntimeHub *hub = &lua_runtime_hub;
    int j;
    {
        scriptRunCtx *bound = luaGetFromRegistry(lua, REGISTRY_RUN_CTX_NAME);
        if (bound)
            hub->current_run_ctx = bound;
    }
    /* Require at least one argument */
    *argc = lua_gettop(lua);
    if (*argc == 0) {
        luaPushError(lua, "Please specify at least one argument for this redis lib call");
        return NULL;
    }

    /* Build the arguments vector (reuse a cached argv from last call) */
    if (hub->argv_size < *argc) {
        hub->argv = zrealloc(hub->argv,sizeof(robj*)* *argc);
        hub->argv_size = *argc;
    }
    *argv_len = hub->argv_size;

    for (j = 0; j < *argc; j++) {
        char *obj_s;
        size_t obj_len;
        char dbuf[64];

        if (lua_type(lua,j+1) == LUA_TNUMBER) {
            /* We can't use lua_tolstring() for number -> string conversion
             * since Lua uses a format specifier that loses precision. */
            lua_Number num = lua_tonumber(lua,j+1);
            obj_len = fpconv_dtoa((double)num, dbuf);
            dbuf[obj_len] = '\0';
            obj_s = dbuf;
        } else {
            obj_s = (char*)lua_tolstring(lua,j+1,&obj_len);
            if (obj_s == NULL) break; /* Not a string. */
        }
        /* Try to use a cached object. */
        if (j < LUA_CMD_OBJCACHE_SIZE && hub->arg_cache[j] &&
            hub->arg_cache_len[j] >= obj_len)
        {
            sds s = hub->arg_cache[j]->ptr;
            hub->argv[j] = hub->arg_cache[j];
            hub->arg_cache[j] = NULL;
            memcpy(s,obj_s,obj_len+1);
            sdssetlen(s, obj_len);
        } else {
            hub->argv[j] = luaRuntimeCreateStringObject(obj_s, obj_len);
        }
    }

    /* Pop all arguments from the stack, we do not need them anymore
     * and this way we guaranty we will have room on the stack for the result. */
    lua_pop(lua, *argc);

    /* Check if one of the arguments passed by the Lua script
     * is not a string or an integer (lua_isstring() return true for
     * integers as well). */
    if (j != *argc) {
        freeLuaRedisArgv(hub->argv, j, hub->argv_size);
        luaPushError(lua, "Lua redis lib command arguments must be strings or integers");
        return NULL;
    }

    return hub->argv;
}

void freeLuaRedisArgv(robj **argv, int argc, int argv_len) {
    luaRuntimeHub *hub = &lua_runtime_hub;
    int j;
    for (j = 0; j < argc; j++) {
        robj *o = argv[j];

        /* Try to cache the object in the hub->arg_cache array.
         * The object must be small, SDS-encoded, and with refcount = 1
         * (we must be the only owner) for us to cache it. */
        if (j < LUA_CMD_OBJCACHE_SIZE &&
            o->refcount == 1 &&
            (o->encoding == OBJ_ENCODING_RAW ||
             o->encoding == OBJ_ENCODING_EMBSTR) &&
            sdslen(o->ptr) <= LUA_CMD_OBJCACHE_MAX_LEN)
        {
            sds s = o->ptr;
            if (hub->arg_cache[j]) luaScriptReleaseObject(hub->arg_cache[j]);
            hub->arg_cache[j] = o;
            hub->arg_cache_len[j] = sdsalloc(s);
        } else {
            luaScriptReleaseObject(o);
        }
    }
    if (argv != hub->argv || argv_len != hub->argv_size) {
        /* The command changed argv, scrap the cache and start over. */
        zfree(argv);
        hub->argv = NULL;
        hub->argv_size = 0;
    }
}

